//! Independent original RNE outputs, not candidate-generated roundtrips.
use super::*;
#[test]
fn original_default_82_bytes_and_all_fifteen_fields() {
    let original = r#"{"freeform_wall":0,"building":8,"roof":0,"building_wall_style":"StoneWithSkirts","freehand_ty":"FollowTerrain","halftimber":0,"lantern_light":0,"fences":0,"window_light":0,"flag":0,"windows":null,"gates":0,"flat_rim_style":"Rim","lantern_brightness":1.0,"stairs":{"stairs_color":100003,"ladder_color":0,"railing_ty":"None","magic_color":0}}"#;
    assert_eq!(
        serde_json::to_string(&GladeColorCustomization::default()).unwrap(),
        original
    );
}
